def is_decimal(text):
    # Accept 2500, 2500.50 and -10. Reject '', '1e3', 'inf', '1.', '.5' and '1,000'.
    if text.startswith('-'):
        text = text[1:]
    parts = text.split('.')
    if len(parts) > 2:
        return False
    return all(part and all(ch in '0123456789' for ch in part) for part in parts)


def parse_rows(csv_text):
    """Return the data rows as (name, salary) pairs, or None if the file must be rejected."""
    lines = [ln.strip() for ln in csv_text.split('\n')]   # strip also removes a Windows '\r'
    lines = [ln for ln in lines if ln]                      # blank lines carry no data
    if not lines:
        return None                                         # no header row at all
    rows = []                                               # lines[0] is the header: skip it unchecked
    for line in lines[1:]:
        fields = line.split(',')
        if len(fields) != 2:
            return None
        name, salary = fields[0].strip(), fields[1].strip()
        if not name or not is_decimal(salary):
            return None
        rows.append((name, float(salary)))
    return rows


def solution(users, csv_text):
    rows = parse_rows(csv_text)
    if rows is None:
        return 'ERROR'                  # validate the whole file before touching the DB
    db = {name: float(salary) for name, salary in users}
    for name, salary in rows:
        if salary >= 0:                 # a negative salary is skipped, not an error
            db[name] = salary           # upsert: later rows win
    return [[name, db[name]] for name in sorted(db)]

