def solution(users, csv_text):
    # Same rules, written longhand: the DB is a list and every upsert scans it.
    lines = []
    for raw in csv_text.split('\n'):
        if raw.strip() != '':
            lines.append(raw.strip())
    if len(lines) == 0:
        return 'ERROR'
    parsed = []
    for line in lines[1:]:
        cells = line.split(',')
        if len(cells) != 2:
            return 'ERROR'
        name = cells[0].strip()
        text = cells[1].strip()
        if name == '':
            return 'ERROR'
        body = text[1:] if text[:1] == '-' else text
        if body.count('.') > 1 or body == '' or body[0] == '.' or body[-1] == '.':
            return 'ERROR'
        for ch in body:
            if ch not in '0123456789.':
                return 'ERROR'
        parsed.append([name, float(text)])
    db = [[u[0], float(u[1])] for u in users]
    for name, salary in parsed:
        if salary < 0:
            continue
        found = False
        for row in db:
            if row[0] == name:
                row[1] = salary
                found = True
        if not found:
            db.append([name, salary])
    db.sort(key=lambda row: row[0])
    return db
